def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Splits a string of nested parentheses into separate balanced groups.
    Spaces are ignored. Raises ValueError on invalid input.
    """
    result = []
    current = []
    depth = 0

    for ch in paren_string:
        if ch.isspace():
            continue
        if ch == '(' or ch == ')':
            current.append(ch)
            depth += 1 if ch == '(' else -1
            if depth < 0:
                raise ValueError("Unbalanced parentheses: too many closing brackets.")
            if depth == 0:
                result.append(''.join(current))
                current.clear()
        else:
            raise ValueError(f"Invalid character '{ch}' in input.")

    if depth != 0:
        raise ValueError("Unbalanced parentheses: unmatched opening brackets remain.")
    return result

