def below_zero(operations: list[int]) -> bool:
    """
    Return True if the cumulative balance ever falls below zero.
    """
    if not isinstance(operations, (list, tuple)):
        raise TypeError("operations must be a list or tuple of numbers")

    balance = 0
    for op in operations:
        if not isinstance(op, (int, float)):
            raise ValueError(f"operation must be numeric, got {type(op).__name__}")
        balance += op
        if balance < 0:
            return True
    return False

