def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    combos = []

    def is_valid(number):
        s = str(number)
        # number must contain only digits 1-9, no zero, no repeats, and at most 9 digits
        return len(s) <= 9 and '0' not in s and len(s) == len(set(s))

    def backtrack(current, used_mask, depth):
        if depth > 0:
            m2 = current * 2
            m3 = current * 3
            if is_valid(m2) and is_valid(m3):
                combos.append((current, m2, m3))
        if depth == 9:
            return
        for i in range(9):          # digits 1 to 9
            if used_mask & (1 << i):
                continue
            backtrack(current * 10 + (i + 1), used_mask | (1 << i), depth + 1)

    try:
        backtrack(0, 0, 0)
    except Exception:
        # In case of unexpected runtime errors, return empty list to satisfy return type
        return []

    # Sort results by the first number in ascending order
    combos.sort(key=lambda x: x[0])
    return combos

