def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication
    signs into the numeric string `num_str` of length N. The string must
    contain only decimal digits. If inserting K signs is impossible
    (e.g., K >= N), the function returns 0.
    """
    # Basic validation
    if not num_str.isdigit():
        raise ValueError("num_str must contain only digits")
    if len(num_str) != N:
        raise ValueError("N does not match the length of num_str")
    if K < 0:
        raise ValueError("K must be non-negative")
    # Impossible to place more than N-1 signs
    if K > N - 1:
        return 0

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(index: int, signs_left: int) -> int:
        """
        Maximum product achievable from substring num_str[index:] using
        exactly `signs_left` multiplication signs.
        """
        # If no signs left, use the rest of the string as a single number
        if signs_left == 0:
            # Convert slice to integer; large numbers handled by Python automatically
            return int(num_str[index:])

        max_prod = 0
        # Determine maximum split point: need at least signs_left digits left after split
        # So j can go up to N - signs_left
        max_split = N - signs_left
        for j in range(index + 1, max_split + 1):
            left_part = int(num_str[index:j])
            right_prod = dp(j, signs_left - 1)
            prod = left_part * right_prod
            if prod > max_prod:
                max_prod = prod
        return max_prod

    return dp(0, K)

