def calculate_scholarship(grades, leader, west, papers):
    """
    Calculate the scholarship amount based on academic grades, leadership status,
    regional affiliation, and published research papers.

    Parameters:
    grades (List[int]): Two-element list [final_average, class_evaluation].
    leader (str): 'Y' if student is class leader, 'N' otherwise.
    west (str): 'Y' if student is from a western province, 'N' otherwise.
    papers (int): Number of published research papers.

    Returns:
    int: Total scholarship amount.
    """
    # Input validation
    try:
        if (
            not isinstance(grades, list)
            or len(grades) != 2
            or not all(isinstance(g, int) for g in grades)
        ):
            raise ValueError("grades must be a list of two integers")
        if leader not in ("Y", "N"):
            raise ValueError("leader must be 'Y' or 'N'")
        if west not in ("Y", "N"):
            raise ValueError("west must be 'Y' or 'N'")
        if not isinstance(papers, int) or papers < 0:
            raise ValueError("papers must be a non‑negative integer")
    except Exception as e:
        raise ValueError(f"Invalid input: {e}") from e

    avg = grades[0]
    class_eval = grades[1]

    scholarship = 0

    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == "Y":
        scholarship += 1000
    if class_eval > 80 and leader == "Y":
        scholarship += 850

    return scholarship

