def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    """
    Selects interview qualifiers based on test scores and a predetermined cutoff derived
    from 150% of the planned recruit count.

    Args:
        n (int): Total number of applicants.
        m (int): Planned number of volunteers to be recruited.
        applicants (List[Tuple[int, int]]): List of (registration number, test score).

    Returns:
        Tuple[int, List[Tuple[int, int]]]: The cutoff score and the list of qualifying
        applicants sorted by score descending and registration number ascending.
    """
    # Basic input validation
    try:
        if not isinstance(n, int) or not isinstance(m, int):
            raise TypeError("n and m must be integers")
        if not isinstance(applicants, list):
            raise TypeError("applicants must be a list of tuples")
        for item in applicants:
            if not (isinstance(item, tuple) and len(item) == 2):
                raise TypeError("each applicant entry must be a tuple of length 2")
            reg, score = item
            if not (isinstance(reg, int) and isinstance(score, int)):
                raise TypeError("registration number and score must be integers")
    except Exception as exc:
        # Return an empty result for invalid input
        return (0, [])

    # If there are no applicants or no planned recruits, nothing qualifies
    if n <= 0 or m <= 0 or not applicants:
        return (0, [])

    # Sort applicants: first by score descending, then by registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Determine the cutoff rank (150% of planned recruits, floored)
    cutoff_rank = int(m * 1.5)  # floor implicitly

    # Handle cases where cutoff rank exceeds the number of applicants or is non-positive
    if cutoff_rank <= 0:
        cutoff_score = sorted_applicants[0][1] if sorted_applicants else 0
    elif cutoff_rank > len(sorted_applicants):
        cutoff_score = sorted_applicants[-1][1]
