def count_partitions(n: int, k: int, x: int) -> int:
    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(x, int):
        raise TypeError("All arguments must be integers")
    if n < 0 or k <= 0 or x < 0:
        return 0
    # reduce the problem by subtracting the minimum required part from each of the k parts
    m = n - k * x
    if m < 0:
        return 0
    # dp[i][j] = number of partitions of integer i into parts of size at most j
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # one way to partition zero
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

