def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.
    """
    # Basic validation
    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(x, int):
        raise TypeError("n, k, and x must be integers")
    if k <= 0:
        return 0
    if n < 0 or x < 0:
        return 0

    # Transform the problem: subtract the minimum part from each part
    m = n - k * x
    if m < 0:
        return 0
    if m == 0:
        return 1  # all parts equal to x

    # Number of partitions of m into at most k positive parts.
    # Equivalent to partitions of m with part sizes at most k.
    dp = [0] * (m + 1)
    dp[0] = 1
    for part in range(1, k + 1):
        for s in range(part, m + 1):
            dp[s] += dp[s - part]
    return dp[m]

