def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.
    Uses dynamic programming (subset sum) to find the maximum occupied volume not exceeding V.
    """
    # Basic validation
    if not isinstance(V, int) or V < 0:
        raise ValueError("Box capacity V must be a non-negative integer.")
    if not isinstance(n, int) or n < 0:
        raise ValueError("Number of items n must be a non-negative integer.")
    if not isinstance(volumes, list):
        raise ValueError("Volumes must be provided as a list.")
    if len(volumes) != n:
        raise ValueError("Length of volumes list must be equal to n.")
    for v in volumes:
        if not isinstance(v, int) or v < 0:
            raise ValueError("Each volume must be a non-negative integer.")

    # If there is no capacity or no items, remaining space is the capacity itself
    if V == 0 or n == 0:
        return V

    # DP array to track achievable volumes
    reachable = [False] * (V + 1)
    reachable[0] = True

    for vol in volumes:
        # If the item's volume alone exceeds V, skip it
        if vol > V:
            continue
        # Update DP table backwards to avoid reuse of the same item
        for cap in range(V, vol - 1, -1):
            if reachable[cap - vol]:
                reachable[cap] = True

    # Find the greatest achievable volume not exceeding V
    max_occupied = max(cap for cap, possible in enumerate(reachable) if possible)

    return V - max_occupied

