    if not isinstance(a, int) or not isinstance(b, int) or b <= 0:
        return None
    try:
        def extended_gcd(x, y):
            if x == 0:
                return (y, 0, 1)
            g, x1, y1 = extended_gcd(y % x, x)
            return (g, y1 - (y // x) * x1, x1)

        g, x, _ = extended_gcd(abs(a), b)
        if g != 1:
            return None
        inv = x % b
        if a < 0:
            inv = (-x) % b
        return inv
    except Exception:
        return None

